const test = require('node:test');
const assert = require('node:assert/strict');
const { totalCents } = require('../parts.cjs');
test('sum integer cents numerically from an empty total', () => {
  const parts = Object.freeze([Object.freeze({cents:60,quantity:2}),Object.freeze({cents:75,quantity:1})]);
  assert.equal(totalCents(parts), 195);
  assert.equal(totalCents([]), 0);
  assert.equal(totalCents([{cents:99,quantity:0}]), 0);
  assert.equal(totalCents([{cents:105,quantity:3},{cents:2,quantity:4}]), 323);
});

test('summing mutable parts preserves quantities and other input fields', () => {
  const parts = [{cents:137,quantity:3,label:'hinge'},{cents:23,quantity:0,label:'clip'}];
  const before = structuredClone(parts);
  assert.equal(totalCents(parts),411);
  assert.deepEqual(parts,before);
  assert.equal(totalCents(parts),411);
});

